    "zeigt": "Schild gegen Bōryokudan im Vergnügungsviertel Nakasu in Fukuoka, 2013",
    "urheber": "Nightingale",
    "lizenz": "CC BY-SA 3.0",
    "herkunft": "https://commons.wikimedia.org/wiki/File:No_Boryokudan_Mark_01.JPG"
